    const header = new THREE.Mesh(
        new THREE.BoxGeometry(DOOR_WIDTH * 2, CAR_HEIGHT - DOOR_HEIGHT, 0.12),
        solidMaterial
    );
    header.position.set(0, DOOR_HEIGHT + (CAR_HEIGHT - DOOR_HEIGHT) / 2, CAR_DEPTH / 2);
    elevatorCar.add(header);

