 * Render loop.
 * ------------------------------------------------------------------ */
function animate(timestamp) {
    requestAnimationFrame(animate);

    const now = timestamp === undefined ? performance.now() : timestamp;
    let deltaSeconds = (now - lastFrameTime) / 1000;
    if (!Number.isFinite(deltaSeconds) || deltaSeconds < 0) {
        deltaSeconds = 0;
    }
