    lastFrameTime = now;

    const scaledDelta = deltaSeconds * simSpeed;
    walkPhase += scaledDelta * 7.5;
    updatePeopleAnimation(scaledDelta);

    for (let i = motions.length - 1; i >= 0; i -= 1) {
        const entry = motions[i];
        const finished = entry.update(scaledDelta) === true;
        if (finished) {
            motions.splice(i, 1);
            if (entry.onDone) {
                entry.onDone();
            }
        }
