const fs = require("fs");
const http = require("http");
const path = require("path");
const { chromium } = require("playwright");

const dir = path.resolve(process.argv[2]);
const shots = path.resolve(process.argv[3] || "/tmp/zoom");
fs.mkdirSync(shots, { recursive: true });

function startServer() {
  const server = http.createServer((req, res) => {
    const requested = path.resolve(dir, `.${decodeURIComponent((req.url || "/").split("?")[0])}`);
    if (!requested.startsWith(dir)) { res.writeHead(403); res.end("no"); return; }
    fs.readFile(requested, (err, data) => {
      if (err) { res.writeHead(404); res.end("nf"); return; }
      const ext = path.extname(requested).toLowerCase();
      res.writeHead(200, { "Content-Type": { ".html": "text/html", ".js": "text/javascript" }[ext] || "text/plain" });
      res.end(data);
    });
  });
  return new Promise((r) => server.listen(0, "127.0.0.1", () => r(server)));
}

(async () => {
  const server = await startServer();
  const port = server.address().port;
  const browser = await chromium.launch({ args: ["--no-sandbox", "--use-gl=swiftshader"] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
  const errors = [];
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
  page.on("pageerror", (e) => errors.push(String(e.message)));
  await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: "load", timeout: 20000 });
  await page.waitForTimeout(1200);

  // Freeze the sim at 1x so the shot is stable, then pick a floor to inspect.
  const info = await page.evaluate(() => {
    const v = new THREE.Vector3();
    const first = people[0];
    first.getWorldPosition(v);
    return { x: v.x, y: v.y, z: v.z, floor: first.userData.floor };
  });
  console.log("inspecting person at", JSON.stringify(info));

  // Side-on close-up of a waiting passenger.
  await page.evaluate((p) => {
    camera.position.set(p.x + 7, p.y + 1.6, p.z + 5);
    camera.lookAt(p.x, p.y + 0.8, p.z);
    controls.target.set(p.x, p.y + 0.8, p.z);
    controls.update();
  }, info);
  await page.waitForTimeout(400);
  await page.screenshot({ path: path.join(shots, "A_person_closeup.png") });

  // Front close-up of the same passenger from behind (we should see the back).
  await page.evaluate((p) => {
    camera.position.set(p.x, p.y + 1.4, p.z + 8);
    camera.lookAt(p.x, p.y + 0.8, p.z);
    controls.target.set(p.x, p.y + 0.8, p.z);
    controls.update();
  }, info);
  await page.waitForTimeout(400);
  await page.screenshot({ path: path.join(shots, "B_person_from_front.png") });

  // Elevator at its floor with doors closed then mid-slide then open.
  await page.evaluate(() => {
    const speed = document.getElementById("speedSlider");
    speed.value = "4";
    speed.dispatchEvent(new Event("input", { bubbles: true }));
  });

  const grab = async (name) => {
    await page.evaluate(() => {
      const v = new THREE.Vector3();
      elevatorCar.getWorldPosition(v);
      camera.position.set(v.x + 8.5, v.y + 3.2, v.z + 9.5);
      controls.target.set(v.x, v.y + 1.1, v.z);
      camera.lookAt(v.x, v.y + 1.1, v.z);
      controls.update();
    });
    await page.waitForTimeout(280);
    await page.screenshot({ path: path.join(shots, name) });
  };
  for (let i = 0; i < 18; i += 1) {
    await grab(`C_car_${String(i).padStart(2, "0")}.png`);
  }
  console.log("console errors:", JSON.stringify(errors));
  await browser.close();
  server.close();
})();
