function slideDoor(door, targetX, step) {
    if (!door) return true;
    const delta = targetX - door.position.x;
    if (Math.abs(delta) < 0.01 || Math.abs(delta) <= step) {
        door.position.x = targetX;
        return true;
    }
    door.position.x += Math.sign(delta) * step;
    return false;
}
