/* Soak test: run many cycles at high speed, watch for errors and invariant drift. */
const fs = require("fs");
const http = require("http");
const path = require("path");
const { chromium } = require("playwright");
const dir = path.resolve(process.argv[2]);
const seconds = Number(process.argv[3] || 40);

function startServer() {
  const server = http.createServer((req, res) => {
    const requested = path.resolve(dir, `.${decodeURIComponent((req.url || "/").split("?")[0])}`);
    if (!requested.startsWith(dir)) { res.writeHead(403); res.end("no"); return; }
    fs.readFile(requested, (err, data) => {
      if (err) { res.writeHead(404); res.end("nf"); return; }
      const ext = path.extname(requested).toLowerCase();
      res.writeHead(200, { "Content-Type": { ".html": "text/html", ".js": "text/javascript" }[ext] || "text/plain" });
      res.end(data);
    });
  });
  return new Promise((r) => server.listen(0, "127.0.0.1", () => r(server)));
}

(async () => {
  const server = await startServer();
  const port = server.address().port;
  const browser = await chromium.launch({ args: ["--no-sandbox", "--use-gl=swiftshader"] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
  page.on("pageerror", (e) => errors.push(String(e.message)));
  await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: "load", timeout: 20000 });
  await page.waitForTimeout(1200);
  await page.evaluate(() => {
    const s = document.getElementById("speedSlider");
    s.value = "20";
    s.dispatchEvent(new Event("input", { bubbles: true }));
  });

  let badFrames = 0;
  const problems = [];
  const v = new THREE.Vector3();
  for (let i = 0; i < seconds * 4; i += 1) {
    await page.waitForTimeout(250);
    const snap = await page.evaluate(() => {
      const vec = new THREE.Vector3();
      const rows = [];
      for (const p of people) {
        p.getWorldPosition(vec);
        const floorY = p.userData.floor * FLOOR_HEIGHT;
        let riding = p.parent === elevatorCar;
        let ok = riding ? Math.abs(vec.y - elevatorCar.position.y) < 0.02
                        : Math.abs(vec.y - floorY) < 0.02;
        rows.push({
          floor: p.userData.floor,
          y: vec.y,
          inCar: riding,
          ok,
          walking: p.userData.isWalking === true,
          feetClear: true
        });
      }
      return { rows, carY: elevatorCar.position.y, doorsOpen };
    });
    if (!snap.rows.length) { problems.push("no people"); break; }
    for (const row of snap.rows) {
      if (!row.ok) { badFrames += 1; problems.push(`floor=${row.floor} y=${row.y.toFixed(3)} carY=${snap.carY.toFixed(3)} inCar=${row.inCar}`); }
    }
    const floors = snap.rows.map((r) => r.floor).sort();
    const unique = new Set(floors);
    if (unique.size !== floors.length) problems.push("duplicate floor assignment: " + floors.join(","));
    if (floors.length !== 5) problems.push("expected 5 passengers, got " + floors.length);
  }
  const final = await page.evaluate(() => {
    const vec = new THREE.Vector3();
    return people.map((p) => {
      p.getWorldPosition(vec);
      return { floor: p.userData.floor, y: Number(vec.y.toFixed(2)), parent: p.parent === scene ? "scene" : (p.parent === elevatorCar ? "car" : "?") };
    });
  });
  console.log("problem samples:", problems.slice(0, 8).join(" | ") || "none");
  console.log("bad person-frames:", badFrames);
  console.log("final:", JSON.stringify(final));
  console.log("console errors:", errors.length, JSON.stringify(errors.slice(0, 5)));
  await browser.close();
  server.close();
})();

